package solution

import (
	"reflect"
	"testing"
)

func TestInspectFieldMatchesOrderTypesAndEligibility(t *testing.T) {
	destination := `package dst

type Destination struct {
	ID, DisplayName string
	Count int
	Payload map[string][]int
	Mismatch []byte
	private string
	Embedded
	Éxtra string
}
type Embedded struct{}
`
	source := `package src

type Source struct {
	id string
	Id string
	displayname string
	DISPLAYNAME string
	COUNT int
	Payload map[string][]int
	Mismatch string
	Embedded
}
`
	got, err := InspectFieldMatches(destination, "Destination", source, "Source")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := []FieldMatch{
		{Destination: "ID", Source: "Id"},
		{Destination: "DisplayName", Source: "DISPLAYNAME"},
		{Destination: "Count", Source: "COUNT"},
		{Destination: "Payload", Source: "Payload"},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("matches = %#v, want %#v", got, want)
	}
}

func TestInspectFieldMatchesAmbiguousSourceName(t *testing.T) {
	destination := `package p; type D struct { Code int; Name string }`
	source := `package p; type S struct { Code int; CODE int; NAME string }`
	got, err := InspectFieldMatches(destination, "D", source, "S")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := []FieldMatch{{Destination: "Name", Source: "NAME"}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("matches = %#v, want %#v", got, want)
	}
}

func TestInspectFieldMatchesEmptyStructs(t *testing.T) {
	got, err := InspectFieldMatches(
		`package p; type D struct{}`,
		"D",
		`package q; type S struct{}`,
		"S",
	)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got == nil || len(got) != 0 {
		t.Fatalf("got %#v; want non-nil empty slice", got)
	}
}

func TestInspectFieldMatchesRejectsBadSourcesAndTypes(t *testing.T) {
	cases := []struct {
		dst, dstName, src, srcName string
	}{
		{`package p; type D struct {`, "D", `package q; type S struct{}`, "S"},
		{`package p; type D struct{}`, "D", `package q; type S struct {`, "S"},
		{`package p; type Other struct{}`, "D", `package q; type S struct{}`, "S"},
		{`package p; type D struct{}`, "D", `package q; type Other struct{}`, "S"},
		{`package p; type D int`, "D", `package q; type S struct{}`, "S"},
		{`package p; type D struct{}`, "D", `package q; type S string`, "S"},
	}
	for i, tc := range cases {
		if got, err := InspectFieldMatches(tc.dst, tc.dstName, tc.src, tc.srcName); err == nil {
			t.Fatalf("case %d: expected error, got %#v", i, got)
		}
	}
}

package solution

import "testing"

func TestReviewASCIIOnlyFold0084(t *testing.T) {
    result, err := InspectFieldMatches("package p; type D struct { AK int }", "D", "package p; type S struct { AK int }", "S")
    if err != nil { t.Fatal(err) }
    if len(result) != 0 { t.Fatalf("ASCII-only lowercase must not fold Kelvin sign: %+v", result) }
}

